// Built-in impulse responses for FALTUNG (generated by tools/gen_irs.py into
// faltung_irs.cc). Every IR is stored as int16 partition spectra ready for
// the partitioned convolution: block 256, FFT 512, ShyFFT sign convention
// (imaginary part negated), textbook scaling (unnormalised forward FFT).
// Per partition and channel: re[0..bins-1] then im[0..bins-1]; im[0] holds
// the Nyquist value when bins == 256. Bins above `bins` are zero (the
// script drops them once they are 60 dB below the partition's energy).

#ifndef MONSOON_DSP_MODES_FALTUNG_IRS_H_
#define MONSOON_DSP_MODES_FALTUNG_IRS_H_

#include <stdint.h>

namespace monsoon {

struct FaltungPartition {
  uint32_t offset;  // into kFaltungData (int16 units)
  uint16_t bins;
  uint16_t reserved;
  float scale;      // multiply the int16 values by this
};

struct FaltungIr {
  const char* name;
  uint16_t partitions;
  uint16_t reserved;
  float peak_gain;  // max |H(f)| over both channels (for the freeze loop)
  const FaltungPartition* part[2];  // [channel][partition]
};

const int kNumFaltungIrs = 8;
extern const FaltungIr kFaltungIrs[kNumFaltungIrs];
extern const int16_t kFaltungData[];

}  // namespace monsoon

#endif  // MONSOON_DSP_MODES_FALTUNG_IRS_H_
